---
import type { ValidatedSentiment, ValidatedSummaryTopics } from "../enrich/validate-output";

export type ProviderUsage = {
  inputTokens?: number | undefined;
  outputTokens?: number | undefined;
  estimated?: boolean | undefined;
};

export type SentimentResult = {
  value: ValidatedSentiment;
  raw: unknown;
  usage: ProviderUsage;
  model: string;
  modelReported?: string;
  origin: "provider" | "mock";
};

export type SummaryTopicsResult = {
  value: ValidatedSummaryTopics;
  raw: unknown;
  usage: ProviderUsage;
  model: string;
  modelReported?: string;
  origin: "provider" | "mock";
};

export type EnrichmentProviders = {
  classifySentiment(text: string, headline: string | null): Promise<SentimentResult>;
  summariseAndTag(text: string, headline: string | null): Promise<SummaryTopicsResult>;
};
---
import { InvalidOutputError } from "../lib/enrich/validate-output";

export type FailureClass = "transient" | "invalid_output" | "permanent";

export function classifyProviderError(err: unknown): FailureClass {
  if (err instanceof InvalidOutputError) return "invalid_output";
  if (!(err instanceof Error)) return "transient";
  const status = (err as Error & { status?: number }).status;
  const msg = err.message.toLowerCase();
  if (msg.includes("invalid output") || msg.includes("unknown_topic")) {
    return "invalid_output";
  }
  if (status === 401 || status === 403 || status === 400) return "permanent";
  if (status && status >= 500) return "transient";
  if (msg.includes("abort") || msg.includes("timeout") || msg.includes("econn")) return "transient";
  if (status && status >= 400 && status < 500) return "permanent";
  return "transient";
}

/** Short, safe string for enrichment_jobs.last_error (no request body / keys). */
export function formatLastError(err: unknown): string {
  if (err instanceof InvalidOutputError) {
    return `invalid_output:${err.reason}`.slice(0, 500);
  }
  if (err instanceof Error) {
    const status = (err as Error & { status?: number }).status;
    const name = err.name || "Error";
    if (status !== undefined) return `${name}:status=${status}`.slice(0, 500);
    // Prefer class name + first clause of message, strip long payloads
    const brief = err.message.split(/[\n{]/)[0]!.trim().slice(0, 200);
    return `${name}:${brief}`.slice(0, 500);
  }
  return String(err).slice(0, 500);
}
---
export const dynamic = "force-dynamic";

import { getConfig } from "@/lib/config";
import { getWebPool } from "@/lib/db/pool";
import { TextBlock } from "@/components/TextBlock";
import { VersionList } from "@/components/upload/VersionList";
import Link from "next/link";
import { notFound } from "next/navigation";

export default async function ArticlePage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const config = getConfig();
  const pool = getWebPool(config.db);

  const art = await pool.query(`SELECT * FROM articles WHERE id = $1`, [id]);
  if (!art.rows[0]) notFound();
  const a = art.rows[0];
  const version = Number(a.version ?? 1);

  const [derived, jobs, transforms, enrichments, dups, versions] = await Promise.all([
    pool.query(
      `SELECT * FROM derived_values WHERE article_id = $1 AND is_current ORDER BY field, rank`,
      [id],
    ),
    pool.query(
      `SELECT * FROM enrichment_jobs WHERE article_id = $1 AND article_version = $2 ORDER BY part`,
      [id, version],
    ),
    pool.query(`SELECT * FROM ingest_transformations WHERE article_id = $1 ORDER BY id`, [id]),
    pool.query(
      `SELECT * FROM enrichments WHERE article_id = $1 AND article_version = $2 ORDER BY created_at`,
      [id, version],
    ),
    pool.query(
      `SELECT id, external_id, source FROM articles WHERE content_hash = $1 AND id <> $2`,
      [a.content_hash, id],
    ),
    pool.query(
      `SELECT version, published_at, ingested_at, superseded_at, language, headline, body, content_hash, flags
         FROM article_versions WHERE article_id = $1 ORDER BY version DESC`,
      [id],
    ),
  ]);

  return (
    <div className="space-y-6">
      <header className="space-y-1">
        <h1 className="text-xl font-semibold">
          {a.headline ? (
            <TextBlock text={a.headline} lang={a.language} as="span" />
          ) : (
            <span className="italic text-muted">(no headline)</span>
          )}
        </h1>
        <p className="text-sm text-muted">
          {a.source} · {a.language} · {new Date(a.published_at).toISOString()} · id {a.id} · v
          {version}
        </p>
      </header>

      {transforms.rows.length > 0 && (
        <p className="text-sm">
          Markup was removed from this article.{" "}
          <a href="#transforms" className="underline">
            What changed
          </a>
        </p>
      )}

      <section>
        <h2 className="font-medium mb-2">Text</h2>
        <TextBlock
          text={a.body ?? ""}
          lang={a.language}
          className="whitespace-pre-wrap text-sm leading-relaxed"
        />
      </section>

      {(versions.rows.length > 0 || version > 1) && (
        <VersionList
          current={{
            version,
            published_at: a.published_at,
            language: a.language,
            headline: a.headline,
            body: a.body,
            content_hash: a.content_hash,
            flags: a.flags ?? [],
          }}
          older={versions.rows}
        />
      )}

      <section>
        <h2 className="font-medium mb-2">Derived values</h2>
        <ul className="space-y-2 text-sm">
          {derived.rows.map((d) => (
            <li key={d.id}>
              <strong>{d.field}</strong>: {d.value}
              {d.confidence_norm != null && ` (${d.confidence_norm}% · ${d.confidence_origin})`}
            </li>
          ))}
          {derived.rows.length === 0 && <li className="text-muted">Not yet enriched</li>}
        </ul>
      </section>

      <section id="transforms">
        <h2 className="font-medium mb-2">What was done to this text</h2>
        <dl className="text-sm space-y-1">
          {transforms.rows.map((t) => (
            <div key={t.id}>
              <dt className="font-medium">
                {t.field}: {t.kind}
              </dt>
              <dd className="text-muted">{JSON.stringify(t.detail)}</dd>
            </div>
          ))}
          {transforms.rows.length === 0 && <p className="text-muted">No transformations recorded</p>}
        </dl>
      </section>

      <section>
        <h2 className="font-medium mb-2">Processing trail</h2>
        <ul className="text-sm space-y-1">
          {jobs.rows.map((j) => (
            <li key={j.id}>
              Job {j.part}: {j.state} · attempts {j.attempts}
              {j.reason_code ? ` · ${j.reason_code}` : ""}
            </li>
          ))}
          {enrichments.rows.map((e) => (
            <li key={e.id}>
              Enrichment {e.part}: {e.provider}/{e.model} · origin {e.origin} · trust {e.trust}
              {e.cost_micro != null ? ` · cost ${e.cost_micro}µ` : ""}
            </li>
          ))}
        </ul>
        {dups.rows.length > 0 && (
          <p className="mt-2 text-sm">
            Same content as:{" "}
            {dups.rows.map((d) => (
              <Link key={d.id} href={`/articles/${d.id}`} className="mr-2">
                {d.source}:{d.external_id}
              </Link>
            ))}
          </p>
        )}
      </section>

      <p>
        <a href={`/api/articles/${id}/trace`} className="text-sm text-accent">
          View trace (JSON)
        </a>
      </p>
    </div>
  );
}

